const K = Math.cos((33.2 * Math.PI) / 180);
const SCALE = 400 / ((49.0 - 38.3) * K);

export function projectIraq(lon: number, lat: number): { x: number; y: number } {
  return { x: (lon - 38.3) * K * SCALE, y: (37.75 - lat) * SCALE };
}
